CREATE proc [dbo].[UspGetItemLedgerKitchenItem]  @From as datetime, @To as Datetime, @BRId as int,  @Adj as int = null  as  select CONVERT(VARCHAR(11),@From,106) as [From], CONVERT(VARCHAR(11),@To,106) as [To],cat.Category, sb.SubCategory, i.ItemId, i.Item, U.Unit as PackingType,  iu.RecpFactor as UnitQty,  (Select Distinct(Unit) from unit  where UId=iu.RecpUnit) as UnitType, ws.Date , [dbo].[GetInvoiceNoForItemledgerReportKitchen](ws.Id)as PINO,  ((select isnull(sum(Qty),0) from WareHouse_Branch where  ItemId = i.ItemId and [Type] = 'In' and Date < @From and PDId = 0 and Did = d.id) - (select isnull(sum(Qty),0) from WareHouse_Branch where  ItemId =i.ItemId and [Type] = 'Out' and Date < @From and PDId = 0 and Did = d.id)) as OpenBalance ,   isnull(sum(ws.Qty),0) as Qty,  (select isnull(sum(Qty),0) from WareHouse_Branch where id = ws.Id and [Type] = 'In' and Did = d.id) as [In],  (select isnull(sum(Qty),0) from WareHouse_Branch where id = ws.Id and [Type] = 'Out' and Did = d.id) as [Out],  (((select isnull(sum(Qty),0) from WareHouse_Branch where  ItemId = i.ItemId and [Type] = 'In' and Date < @From and PDId = 0 and Did = d.id) - (select isnull(sum(Qty),0) from WareHouse_Branch where  ItemId =i.ItemId and [Type] = 'Out' and Date < @From and PDId = 0 and Did = d.id)) + (select isnull(sum(Qty),0) from WareHouse_Branch where id = ws.Id and [Type] = 'In' and ItemId = i.ItemId and Did = d.id) - (select isnull(sum(Qty),0) from WareHouse_Branch where id = ws.Id and [Type] = 'Out' and ItemId = i.ItemId and Did = d.id)) as [Balance],  br.Branch as [Type], d.department_name as [Desc]  from Item i   left join WareHouse_Branch ws on i.ItemId = ws.ItemId  inner join SubCategory sb on sb.SBId = i.SBId  inner join Category cat on cat.CId = sb.CId  inner join ItemUnit iu on i.ItemId=iu.ItemId  inner join Unit U on iu.IssUnit=U.UId  inner join Branch br on ws.BRId = br.BRId  inner join DepartmentPos d on br.BRId = d.BRId  where   ws.Date between @From and @To  and ws.BRId = @BRId  and ws.DId = d.id and (ws.InvAdjId = @Adj or @Adj is null)  group by i.ItemId,i.Item,ws.Date ,ws.Id,cat.Category,sb.SubCategory,U.Unit,iu.RecpFactor ,iu.RecpUnit,br.Branch,d.department_name,d.id order by d.department_name,i.Item,ws.Date,ws.Id